import{c as a,Q as t,j as r,m as o}from"./chunks/framework.BXc4yaFE.js";const d=JSON.parse('{"title":"Experience as a Compass: Multi-agent RAG with Evolving Orchestration and Agent Prompts","description":"","frontmatter":{"url":"https://arxiv.org/abs/2604.00901","title":"Experience as a Compass: Multi-agent RAG with Evolving Orchestration and Agent Prompts","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2604.00901,"authors":["Sha Li","Naren Ramakrishnan"],"domains":["cs.AI"],"html":"https://arxiv.org/html/2604.00901v1","pdf_path":"pdfs/2604.00901.pdf","published_date":"2026-04-01T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-04-01-experience-as-compass-multi-agent-rag-hera-2604-00901.md","filePath":"research/papers/2026-04-01-experience-as-compass-multi-agent-rag-hera-2604-00901.md","lastUpdated":1785909234000}'),i={name:"research/papers/2026-04-01-experience-as-compass-multi-agent-rag-hera-2604-00901.md"};function n(s,e,l,c,p,g){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="experience-as-a-compass-multi-agent-rag-with-evolving-orchestration-and-agent-prompts" tabindex="-1">Experience as a Compass: Multi-agent RAG with Evolving Orchestration and Agent Prompts <a class="header-anchor" href="#experience-as-a-compass-multi-agent-rag-with-evolving-orchestration-and-agent-prompts" aria-label="Permalink to &quot;Experience as a Compass: Multi-agent RAG with Evolving Orchestration and Agent Prompts&quot;">​</a></h1><p><strong>Authors</strong>: Sha Li, Naren Ramakrishnan <strong>Published</strong>: April 1, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2604.00901" target="_blank" rel="noreferrer">https://arxiv.org/abs/2604.00901</a> · <a href="https://arxiv.org/html/2604.00901v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2604.00901 <strong>Categories</strong>: cs.AI <strong>PDF</strong>: <a href="https://arxiv.org/abs/2604.00901" target="_blank" rel="noreferrer">research/papers/pdfs/2604.00901.pdf</a> (32 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Multi-agent Retrieval-Augmented Generation (RAG), wherein each agent takes on a specific role, supports hard queries that require multiple steps and sources, or complex reasoning. Existing approaches, however, rely on static agent behaviors and fixed orchestration strategies, leading to brittle performance on diverse, multi-hop tasks. We identify two key limitations: the lack of continuously adaptive orchestration mechanisms and the absence of behavior-level learning for individual agents. To this end, we propose HERA, a hierarchical framework that jointly evolves multi-agent orchestration and role-specific agent prompts. At the global level, HERA optimizes query-specific agent topologies through reward-guided sampling and experience accumulation. At the local level, Role-Aware Prompt Evolution refines agent behaviors via credit assignment and dual-axes adaptation along operational and behavioral principles, enabling targeted, role-conditioned improvements. On six knowledge-intensive benchmarks, HERA achieves an average improvement of 38.69% over recent baselines while maintaining robust generalization and token efficiency. Topological analyses reveal emergent self-organization, where sparse exploration yields compact, high-utility multi-agent networks, demonstrating both efficient coordination and robust reasoning.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出 <strong>HERA</strong>，一個階層式（hierarchical）框架，<strong>同時演化</strong> multi-agent orchestration（協作拓撲）與 role-specific agent prompts（角色提示），解決現有 multi-agent RAG 依賴 static behavior + fixed orchestration 的脆弱性。</li><li><strong>Global level</strong>：以 reward-guided sampling + experience accumulation，針對每個 query 優化 query-specific agent topology（讓協作結構隨任務調整，而非固定）。</li><li><strong>Local level</strong>：提出 <strong>Role-Aware Prompt Evolution</strong>，透過 credit assignment 與 dual-axes adaptation（operational 與 behavioral 兩軸）對個別 agent 行為做 role-conditioned 的針對性改進。</li><li>將「過往經驗」當作導航羅盤（experience as a compass）—— 把累積的試驗訊號回饋進拓撲取樣與 prompt 演化，形成自我改進迴路。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>在 <strong>six knowledge-intensive benchmarks</strong> 上，相較近期 baselines 平均提升 <strong>38.69%</strong>。</li><li>維持 robust generalization 與 token efficiency（非以爆量 token 換準確率）。</li><li>Topological 分析顯示 <strong>emergent self-organization</strong>：sparse exploration 收斂出 compact、high-utility 的 multi-agent network —— 兼具 efficient coordination 與 robust reasoning。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><p>文件未列明確 limitation 章節（基於 abstract 與後設資料判斷）。可能弱點：</p><ul><li>「38.69% 平均提升」為跨 6 benchmark 平均，未在 abstract 揭露各 benchmark 變異與最差案例；可能掩蓋特定任務退化。</li><li>reward-guided sampling + 經驗累積屬 online 演化，<strong>收斂成本 / 冷啟動（cold-start）開銷</strong>未在摘要量化，token efficiency 宣稱需看完整評估的 per-query 成本。</li><li>emergent self-organization 為觀察性結論，未說明拓撲穩定性與跨 domain 遷移時是否需重新演化。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>自我演化迴路對應</strong>：HERA 的「experience accumulation → 回饋進 topology / prompt 演化」與 The Loop 的 RECORD 階段（結構化反思入庫、下次注入）同構；可作為 workspace 自我演化「機械驗證入庫、退化可觀測」設計的外部參照。⚠️ 落地門檻：HERA 的 reward 訊號來自 benchmark ground truth，workspace 任務多無此 dense reward，需先解決 evaluator 訊號來源。</li><li><strong>Role-Aware Prompt Evolution vs auto-load 規則進化</strong>：dual-axes（operational / behavioral）credit assignment 的思路，可對照 <code>autoload-evolution</code> skill 的「識別 Gap → 提案 → 驗證」閉環。⚠️ HERA 是 per-query online 演化；workspace 規則進化是離線、≤1 規則/cycle 的保守節奏，兩者風險容忍度不同，不可直接移植。</li><li><strong>multi-agent orchestration vs subagent fan-out</strong>：HERA 的 query-specific topology 自適應，對照 <code>core.md §PROPOSE 委派</code>（原 <code>subagent-strategy.md</code>）的固定 fan-out ≤4 + hierarchical parent↔child 規則 —— 提供「動態拓撲」是否值得引入的思考素材。⚠️ workspace 現行紀律刻意限制動態性以控 token/可預測性，引入前需評估 goal drift 風險。 〔v5.1：所引 workspace 細則已退役 → 見 <code>INDEX.md</code> §v5.1 規則退役對照〕</li><li><strong>memory-compactor 連結</strong>：HERA 把經驗壓縮成 compact high-utility network，與 <code>memory-compactor</code>（保留決策、移除冗餘）目標相近，可作為「經驗壓縮如何不損失 high-utility 訊號」的對照。⚠️ 純概念對照，無共用實作。</li></ul>',17)])])}const u=a(i,[["render",n]]);export{d as __pageData,u as default};
